float softTurn(float t) {
 t=clamp(t,0.,1.);
 return t*t*t*(t*(t*6.-15.)+10.);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec4 original=vrchSampleSource0(uv);
 vec2 grid=iResolution.xy/min(iResolution.x,iResolution.y)*uParam_blocks;
 vec2 cell=floor(uv*grid),local=fract(uv*grid)-.5;
 vec2 textureSize=ceil(grid)*vec2(1.,2.);
 vec4 event=vrchSampleSignalTexture(0,(cell+.5)/textureSize);
 vec4 gesture=vrchSampleSignalTexture(0,(cell+vec2(.5,ceil(grid.y)+.5))/textureSize);
 float duration=gesture.x>0.?gesture.x:uParam_duration;
 float hold=gesture.x>0.?gesture.y:.04;
 float perspective=gesture.x>0.?gesture.z:.48;
 float age=iTime-event.x,halfTurn=duration*.5;
 bool turning=event.z>.5 && (gesture.w<.5 || uParam_note_response>0.) && uParam_density>0. && age>=0. && age<duration+hold;
 float turn=0.;
 if(turning) {
  if(age<halfTurn)turn=3.14159265*softTurn(age/halfTurn);
  else if(age<halfTurn+hold)turn=3.14159265;
  else turn=3.14159265*(1.+softTurn((age-halfTurn-hold)/halfTurn));
 }
 bool restingBack=turning && age>=halfTurn && age<=halfTurn+hold;
 float face=restingBack?-1.:cos(turn),sine=restingBack?0.:sin(turn);
 bool horizontal=mod(event.y,2.)>.5;
 // Each tile has a stable phase; sustained music advances it continuously.
 float phase=vrchPhase_flow_speed();
 float identity=fract(sin(dot(cell,vec2(127.1,311.7)))*43758.5453);
 float drift=phase*.32+identity*6.2831853;
 vec2 offset=.026*uParam_float_amount*vec2(sin(drift),cos(drift*.73+identity*3.));
 float lift=uParam_float_amount*.5*(.5+.5*sin(drift*.81+1.));
 offset.y+=.035*lift;
 vec2 floating=(local-offset)/max(.8,1.-.20*lift);
 floating.y+=floating.x*.025*uParam_float_amount*sin(drift*.63);
 vec2 q=horizontal?floating.yx:floating;
 float projectedFace=face<0.?-max(abs(face),.004):max(abs(face),.004);
 float x=q.x/(projectedFace+q.x*sine*perspective);
 vec2 paper=vec2(x,q.y*(1.-x*sine*perspective));
 float aa=(grid.y/iResolution.y)/max(abs(face),.04);
 float edge=max(abs(paper.x),abs(paper.y));
 float inside=1.-smoothstep(.5-.008-aa*.5,.5-.008+aa*.5,edge);
 // Each face carries its full image region. Correct the back's orientation
 // so image B is readable when it faces the audience.
 vec2 imageLocal=vec2(paper.x*(face<0.?-1.:1.),paper.y);
 if(horizontal)imageLocal=imageLocal.yx;
 vec2 imageUv=(cell+.5+imageLocal)/grid;
 vec4 picture=face<0. && uVrchSource1Valid?vrchSampleSource1(imageUv):vrchSampleSource0(imageUv);
 float light=1.-.2*(1.-abs(face));
 // A softly shaded image remains under the turning face, avoiding a
 // black square flash when a whole batch crosses its thin edge.
 float reveal=turning?pow(abs(sin(turn)),2.):0.;
 vec3 backing=mix(vec3(.012),original.rgb*.72,reveal);
 vec3 result=mix(backing,picture.rgb*light,inside);
 float sweep=dot(imageLocal,normalize(vec2(.8,.6)))+.62*sin(phase*.47+identity*5.);
 float sheen=exp(-sweep*sweep/.025);
 float softEdge=pow(clamp(1.-2.*max(abs(paper.x),abs(paper.y)),0.,1.),.25);
 vec3 reflection=vec3(.94,.97,1.)*sheen*uParam_reflection*.18;
 result+=reflection*inside*softEdge*(.35+.65*abs(face));
 fragColor=vec4(mix(original.rgb,result,uParam_amount),mix(original.a,picture.a,uParam_amount));
}
